// Any reason value not listed for the code = e_reason.
inline constexpr bool reason_allowed(std::uint16_t c, std::uint16_t reason) {
    const CodeTable* t = find_code(c);
    if (!t) return false;
    for (std::size_t i = 0; i < t->reason_count; ++i)
        if (t->reasons[i].value == reason) return true;
    return false;
}
inline constexpr std::string_view reason_value_name(std::uint16_t c, std::uint16_t reason) {
    const CodeTable* t = find_code(c);
    if (t)
        for (std::size_t i = 0; i < t->reason_count; ++i)
            if (t->reasons[i].value == reason) return t->reasons[i].name;
    return "unknown";
}
